package com.example.notificationservice.controller;

import com.example.notificationservice.dto.NotificationDTO;
import com.example.notificationservice.service.NotificationService;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.responses.ApiResponse;
import io.swagger.v3.oas.annotations.responses.ApiResponses;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@Slf4j
@RestController
@RequestMapping("/api/v1/notifications")
@RequiredArgsConstructor
@Tag(name = "Notification", description = "Email notification dispatch")
public class NotificationController {

    private final NotificationService notificationService;

    @PostMapping("/send")
    @Operation(summary = "Send a notification email synchronously")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Notification sent"),
            @ApiResponse(responseCode = "400", description = "Invalid request or email format"),
            @ApiResponse(responseCode = "500", description = "Mail delivery failed")
    })
    public ResponseEntity<String> sendNotification(@Valid @RequestBody NotificationDTO notificationDTO) {
        log.info("Sync notification request for receiver={}", notificationDTO.getReceiver());
        return ResponseEntity.ok(notificationService.sendNotification(notificationDTO));
    }
}

package com.example.notificationservice.controller;

import com.example.notificationservice.dto.NotificationDTO;
import com.example.notificationservice.dto.response.NotificationResponse;
import com.example.notificationservice.service.NotificationService;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.responses.ApiResponse;
import io.swagger.v3.oas.annotations.responses.ApiResponses;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.web.PageableDefault;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@Slf4j
@RestController
@RequestMapping("/api/v1/notifications")
@RequiredArgsConstructor
@Tag(name = "Notification", description = "Email notification dispatch")
public class NotificationController {

    private final NotificationService notificationService;

    @PostMapping("/send")
    @Operation(summary = "Send a notification email synchronously")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Notification sent"),
            @ApiResponse(responseCode = "400", description = "Invalid request or email format"),
            @ApiResponse(responseCode = "500", description = "Mail delivery failed")
    })
    public ResponseEntity<String> sendNotification(@Valid @RequestBody NotificationDTO notificationDTO) {
        log.info("Sync notification request for receiver={}", notificationDTO.getReceiver());
        return ResponseEntity.ok(notificationService.sendNotification(notificationDTO));
    }

    @GetMapping
    @Operation(summary = "Get all notifications (paginated)")
    @ApiResponse(responseCode = "200", description = "List of notifications")
    public ResponseEntity<Page<NotificationResponse>> getAllNotifications(
            @PageableDefault(size = 20, sort = "createdAt") Pageable pageable) {
        return ResponseEntity.ok(notificationService.getAllNotifications(pageable));
    }

    @GetMapping("/receiver/{email}")
    @Operation(summary = "Get notifications by receiver email (paginated)")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Notifications for receiver"),
            @ApiResponse(responseCode = "400", description = "Invalid email")
    })
    public ResponseEntity<Page<NotificationResponse>> getByReceiver(
            @PathVariable String email,
            @PageableDefault(size = 20, sort = "createdAt") Pageable pageable) {
        log.debug("Fetching notifications for receiver={}", email);
        return ResponseEntity.ok(notificationService.getNotificationsByReceiver(email, pageable));
    }

    @GetMapping("/status/{status}")
    @Operation(summary = "Get notifications by status (SENT | FAILED | PENDING)")
    @ApiResponse(responseCode = "200", description = "Notifications filtered by status")
    public ResponseEntity<Page<NotificationResponse>> getByStatus(
            @PathVariable String status,
            @PageableDefault(size = 20, sort = "createdAt") Pageable pageable) {
        log.debug("Fetching notifications with status={}", status);
        return ResponseEntity.ok(notificationService.getNotificationsByStatus(status, pageable));
    }
}

package com.example.notificationservice.service;

import com.example.notificationservice.Repo.NotificationRepository;
import com.example.notificationservice.dto.NotificationDTO;
import com.example.notificationservice.entity.Notification;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.amqp.rabbit.annotation.RabbitListener;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.mail.SimpleMailMessage;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.stereotype.Service;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
@Service
@RequiredArgsConstructor
public class NotificationService {

    private final JavaMailSender mailSender;
    private final NotificationRepository notificationRepository;

    @Value("${spring.mail.username}")
    private String fromEmail;

    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+$");

    /**
     * Primary consumer: processes notification events from RabbitMQ asynchronously.
     * On processing failure the message is negatively acknowledged and routed to DLQ.
     */
    @RabbitListener(queues = "${account.queue.json.name}", ackMode = "AUTO")
    public void handleNotificationEvent(NotificationDTO notificationDTO) {
        log.info("Received async notification event for receiver={}", notificationDTO.getReceiver());
        try {
            String result = sendNotification(notificationDTO);
            log.info("Async notification processed: receiver={}, result={}", notificationDTO.getReceiver(), result);
        } catch (Exception e) {
            log.error("Failed to process async notification for receiver={}: {}",
                    notificationDTO.getReceiver(), e.getMessage());
            throw e; // re-throw so Spring AMQP routes to DLQ
        }
    }

    /**
     * Synchronous endpoint: called directly via REST POST /api/v1/notifications/send
     */
    public String sendNotification(NotificationDTO notificationDTO) {
        validateNotification(notificationDTO);

        try {
            SimpleMailMessage message = new SimpleMailMessage();
            message.setFrom(fromEmail);
            message.setTo(notificationDTO.getReceiver());
            message.setSubject(notificationDTO.getSubject());
            message.setText(notificationDTO.getBody());
            mailSender.send(message);
            log.info("Email sent to={}", notificationDTO.getReceiver());
        } catch (Exception e) {
            log.error("Mail delivery failed for receiver={}: {}", notificationDTO.getReceiver(), e.getMessage());
            // Persist with FAILED status so it's traceable
            saveNotification(notificationDTO, "FAILED");
            throw e;
        }

        saveNotification(notificationDTO, "SENT");
        return "Notification sent successfully";
    }

    private void validateNotification(NotificationDTO dto) {
        if (dto.getReceiver() == null || dto.getReceiver().isBlank()) {
            throw new IllegalArgumentException("Receiver email is required");
        }
        Matcher matcher = EMAIL_PATTERN.matcher(dto.getReceiver());
        if (!matcher.matches()) {
            throw new IllegalArgumentException("Invalid email format: " + dto.getReceiver());
        }
        if (dto.getSubject() == null || dto.getSubject().isBlank()) {
            throw new IllegalArgumentException("Subject is required");
        }
        if (dto.getBody() == null || dto.getBody().isBlank()) {
            throw new IllegalArgumentException("Body is required");
        }
    }

    private void saveNotification(NotificationDTO dto, String status) {
        notificationRepository.save(Notification.builder()
                .receiver(dto.getReceiver())
                .subject(dto.getSubject())
                .body(dto.getBody())
                .status(status)
                .build());
    }
}

package com.example.notificationservice.service;

import com.example.notificationservice.Repo.NotificationRepository;
import com.example.notificationservice.dto.NotificationDTO;
